#include "Vresident_component_top.h"
#include "resident_metadata.hpp"
#include <iostream>
using namespace resident_event;
int main(){Vresident_component_top v;Controller c(11,64,2112);uint64_t checks=0;int retired=0;for(int t=0;t<6000;t++){Controller::Inputs i;i.reset=t==0||t==3500;i.launch_valid=t>2&&t<200||t>3503&&t<3550;i.launch_id=t;i.row=t%64;i.col=t%66;i.a=0x10000;i.b=0x1000000;i.c=0x3000000;i.done_ready=t%7!=0;i.staging_ready=t%3!=0;i.compute_ready=t%4!=0;i.scratch_ready=true;i.producer_release.resize(11);i.consumer_release.resize(11);i.consumer_arrival.resize(11);for(int n=0;n<11;n++){i.producer_release[n]=c.ctx[n].state==Controller::STAGE_WAIT;i.consumer_release[n]=c.ctx[n].state==Controller::COMPUTE_WAIT;i.consumer_arrival[n]=c.ctx[n].state==Controller::COMPUTE_WAIT?15:0;if(!i.staging_done&&c.ctx[n].state==Controller::STAGE_WAIT&&c.ctx[n].producer){i.staging_done=true;i.staging_context=n;i.staging_id=c.ctx[n].stage;}if(!i.compute_done&&c.ctx[n].state==Controller::COMPUTE_WAIT&&c.ctx[n].consumer){i.compute_done=true;i.compute_context=n;i.compute_id=c.ctx[n].stage;}}
i.scratch_response=c.output_owner>=0&&c.ctx[c.output_owner].state==Controller::OUTPUT_WAIT;i.scratch_id=c.output_owner>=0?c.output_owner:0;i.store_ready=t%3!=0;i.store_response=c.store_wait&&t%5!=0;i.store_id=c.output_owner>=0?c.output_owner*32+c.ordinal:0;auto s=c.signals(i);v.clk=0;v.rst=i.reset;v.launch_valid=i.launch_valid;v.done_ready=i.done_ready;v.staging_ready=i.staging_ready;v.staging_done_valid=i.staging_done;v.compute_ready=i.compute_ready;v.compute_rsp_valid=i.compute_done;v.scratch_req_ready=i.scratch_ready;v.scratch_rsp_valid=i.scratch_response;v.store_req_ready=i.store_ready;v.store_rsp_valid=i.store_response;v.write_warp_valid=0;v.staging_commit_ready=0;v.scratch_store_grant=0;v.launch_id=i.launch_id;v.cta_row=i.row;v.cta_col=i.col;v.a_base=i.a;v.b_base=i.b;v.c_base=i.c;v.staging_done_context=i.staging_context;v.staging_done_id=i.staging_id;v.compute_rsp_context=i.compute_context;v.compute_rsp_id=i.compute_id;v.scratch_rsp_id=i.scratch_id;v.store_rsp_id=i.store_id;for(int n=0;n<11;n++){v.producer_release_valid[n]=i.producer_release[n];v.consumer_release_valid[n]=i.consumer_release[n];v.consumer_arrival_mask[n]=i.consumer_arrival[n];}v.eval();if(!i.reset){auto eq=[&](int64_t x,int64_t y,const char*n){checks++;if(x!=y){std::cerr<<t<<" "<<n<<" "<<x<<" "<<y<<"\n";std::exit(1);}};
#define EQ(x,y) eq(int32_t(v.x),int32_t(y),#x)
EQ(launch_ready,s.launch_ready);EQ(done_valid,s.done);EQ(staging_valid,s.staging);EQ(compute_valid,s.compute);EQ(staging_done_ready,s.staging_done_ready);EQ(compute_rsp_ready,s.compute_done_ready);EQ(scratch_req_valid,s.scratch);EQ(store_req_valid,s.store);EQ(store_rsp_ready,s.store_response_ready);EQ(scratch_rsp_ready,s.scratch_response_ready);EQ(done_id,s.done_id);EQ(done_context,s.done_context);EQ(staging_context,s.stage_context);EQ(staging_id,s.stage_id);EQ(compute_context,s.compute_context);EQ(compute_id,s.compute_id);EQ(store_id,s.store_id);EQ(stage_owner,c.stage_owner);EQ(compute_owner,c.compute_owner);EQ(output_owner,c.output_owner);EQ(result_owner,c.result_owner);EQ(stage_cursor,c.stage_cursor);EQ(compute_cursor,c.compute_cursor);EQ(output_cursor,c.output_cursor);EQ(result_cursor,c.result_cursor);EQ(store_ordinal,c.ordinal);EQ(store_wait,c.store_wait);for(int n=0;n<11;n++){eq(v.state_out[n],c.ctx[n].state,"ctxstate");eq(v.stage_out[n],c.ctx[n].stage,"ctxstage");eq(v.producer_out[n],c.ctx[n].producer,"producer");eq(v.consumer_out[n],c.ctx[n].consumer,"consumer");eq(v.seen_out[n],c.ctx[n].seen,"seen");}retired+=s.done&&i.done_ready;}v.clk=1;v.eval();c.edge(i);}std::cout<<"RESIDENT_METADATA_PASS cycles=6000 checks="<<checks<<" retired="<<retired<<"\n";}
